// Exact cloud wire shapes; root/role identity is verified independently of grant state.
// v2's imTemporaryRootsIncluded=false is a legacy constant, NOT a scope inventory.
// Preserve it for immutable controllers; actual scope is sendRoots (plan.scope.sendRoots).
// Consumers must not use it to infer inclusion/exclusion of an explicitly selected IM directory.
import path from 'node:path';
import {digest} from './onboarding-ssh.js';
const exact=(v,ks)=>v&&typeof v==='object'&&!Array.isArray(v)&&Object.keys(v).sort().join()===ks.slice().sort().join();
const uuid=v=>typeof v==='string'&&/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/.test(v),hex=v=>typeof v==='string'&&/^[a-f0-9]{64}$/.test(v),rev=v=>Number.isSafeInteger(v)&&v>=0&&v<Number.MAX_SAFE_INTEGER-1;
const fail=()=>{throw Error('ONBOARDING_FILES_RESPONSE_REVIEW');};
const abs=v=>typeof v==='string'&&v.length<=4096&&v.startsWith('/')&&path.posix.normalize(v)===v&&!/[\x00-\x1f\x7f]/u.test(v);
function limits(v){if(!exact(v,['maxBytes','queueEntries','chunkBytes','automaticDeletion'])||v.maxBytes!==2097152||v.queueEntries!==64||v.chunkBytes!==49152||v.automaticDeletion!==false)fail();}
export function fileConfigurationInput(v){if(!exact(v,['enabled','sendRoots','maxBytes'])||typeof v.enabled!=='boolean'||!Array.isArray(v.sendRoots)||v.sendRoots.length>8||!v.sendRoots.every(abs)||new Set(v.sendRoots).size!==v.sendRoots.length||!Number.isSafeInteger(v.maxBytes)||v.maxBytes<1||v.maxBytes>2097152)fail();return v;}
function scope(s){if(!exact(s,['runtimeId','role','namespace','root','rootIdentity','sendRoots','receiveRoot','maxBytes'])||!uuid(s.runtimeId)||s.role!=='cloud'||s.namespace!=='managed-'+s.runtimeId||!abs(s.root)||path.posix.basename(s.root)!==s.runtimeId||!/^\d+:\d+$/.test(s.rootIdentity)||s.receiveRoot!==s.root+'/files/inbox'||!Array.isArray(s.sendRoots)||!s.sendRoots.length||s.sendRoots.some(x=>!exact(x,['path','identity'])||!abs(x.path)||typeof x.identity!=='string'||!(x.path===s.root+'/files/outbox'?x.identity==='owned-outbox':/^\d+:\d+$/.test(x.identity))))fail();fileConfigurationInput({enabled:true,sendRoots:s.sendRoots.map(x=>x.path),maxBytes:s.maxBytes});}
export function cloudFilePlan(v){if(v?.kind==='scope_migration')return cloudFileMigrationPlan(v);if(!exact(v,['id','expectedRevision','enabled','scope','expiresAt','fingerprint','contract','limits','writes','modelRequests','imTemporaryRootsIncluded','repositoryWriteAuthorized','executionAuthorized'])||v.contract!==2||!uuid(v.id)||!rev(v.expectedRevision)||typeof v.enabled!=='boolean'||!Number.isSafeInteger(v.expiresAt)||!hex(v.fingerprint)||v.writes!==0||v.modelRequests!==0||v.imTemporaryRootsIncluded!==false||v.repositoryWriteAuthorized!==false||v.executionAuthorized!==false)fail();scope(v.scope);limits(v.limits);return v;}
export function fileMigrationInput(v){if(!exact(v,['sendRoots','maxBytes']))fail();fileConfigurationInput({...v,enabled:false});return v;}
export function cloudFileMigrationPlan(v){
 const fields=['id','expectedRevision','enabled','scope','migration','expiresAt','fingerprint','contract','kind','limits','writes','modelRequests','preservesFiles','holdsPendingTransfers','requiresSeparateEnable','executionAuthorized','repositoryWriteAuthorized'];
 if(!exact(v,fields)||v.contract!==1||v.kind!=='scope_migration'||!uuid(v.id)||!rev(v.expectedRevision)||v.expectedRevision<1||v.enabled!==false||!Number.isSafeInteger(v.expiresAt)||!hex(v.fingerprint)||v.writes!==0||v.modelRequests!==0||v.preservesFiles!==true||v.holdsPendingTransfers!==true||v.requiresSeparateEnable!==true||v.executionAuthorized!==false||v.repositoryWriteAuthorized!==false||!exact(v.migration,['previousScope','snapshot']))fail();
 scope(v.scope);scope(v.migration.previousScope);limits(v.limits);const old=v.migration.previousScope,s=v.scope,z=v.migration.snapshot;
 if(['runtimeId','role','namespace','root','rootIdentity','receiveRoot'].some(k=>s[k]!==old[k])||digest(s)===digest(old)||!exact(z,['ownerHash','queueHash','held'])||!hex(z.ownerHash)||!hex(z.queueHash)||!exact(z.held,['outgoing','incoming','broker'])||!Object.values(z.held).every(x=>rev(x)&&x<=64))fail();return v;
}
export function cloudFileStatus(v){
 if(v?.available===false){if(!exact(v,['contract','available','state','executionAuthorized','repositoryWriteAuthorized'])||v.contract!==2||v.state!=='runtime_required'||v.executionAuthorized!==false||v.repositoryWriteAuthorized!==false)fail();return v;}
 const fields=['contract','available','scope','scopeHash','role','runtimeId','namespace','revision','appliedOperation','appliedPlanHash','enabled','active','state','sendRoots','receiveRoot','maxBytes','limits','counts','error','imTemporaryRootsIncluded','repositoryWriteAuthorized','executionAuthorized','automaticDeletion'];
 if(!exact(v,[...fields,...(v?.notReapplied!==undefined?['notReapplied']:[])])||v.notReapplied!==undefined&&v.notReapplied!==true||v.contract!==2||v.available!==true||v.scope!=='current_managed_host_only'||v.role!=='cloud'||!uuid(v.runtimeId)||v.namespace!=='managed-'+v.runtimeId||!rev(v.revision)||typeof v.enabled!=='boolean'||typeof v.active!=='boolean'||v.active&&!v.enabled||v.enabled&&!hex(v.scopeHash)||v.scopeHash!==null&&!hex(v.scopeHash)||!abs(v.receiveRoot)||!v.receiveRoot.endsWith('/'+v.runtimeId+'/files/inbox')||v.imTemporaryRootsIncluded!==false||v.repositoryWriteAuthorized!==false||v.executionAuthorized!==false||v.automaticDeletion!==false||v.error!==null&&!/^ONBOARDING_FILES_[A-Z_]+$/.test(v.error))fail();
 fileConfigurationInput({enabled:v.enabled,sendRoots:v.sendRoots,maxBytes:v.maxBytes});if(!v.sendRoots.length||!exact(v.counts,['outgoing','incoming','broker'])||!Object.values(v.counts).every(x=>rev(x)&&x<=64))fail();limits(v.limits);
 if(v.revision===0){if(v.appliedOperation!==null||v.appliedPlanHash!==null||v.enabled||v.active||v.scopeHash!==null)fail();}else if(!uuid(v.appliedOperation)||!hex(v.appliedPlanHash))fail();
 if(v.state!==(v.active?'active':v.error?'needs_review':v.enabled?'activation_pending':v.revision?'disabled':'not_configured'))fail();return v;
}
export function bindCloudFiles(v,target){const root=target.root+'/runtime/native-home/dsh/dual-host-task-runtime/';if(v.scope&&typeof v.scope==='object'){if(v.scope.root!==root+v.scope.runtimeId)fail();}else if(v.available&&v.receiveRoot!==root+v.runtimeId+'/files/inbox')fail();return v;}
export const fileAuthorizationHash=v=>digest({runtimeId:v.runtimeId,enabled:v.enabled,scopeHash:v.scopeHash});
